//! Native Rust definitions for core WAFER types.
//!
//! These types were previously generated by `wit-bindgen` from the WIT interface
//! definitions. They are now hand-written to remove the wasmtime/WIT dependency
//! as part of the migration to wasmi + JSON ABI.

use std::fmt;

use serde::{Deserialize, Serialize};

/// A key-value metadata entry.
#[derive(Debug, Clone, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub struct MetaEntry {
    /// Dotted key name (e.g. `req.action`, `auth.user_id`). See [`crate::meta`]
    /// for the well-known constants.
    pub key: String,
    /// String-encoded value associated with `key`.
    pub value: String,
}

/// A message flowing through the block flow.
#[derive(Debug, Clone, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub struct Message {
    /// Message kind/action discriminator (e.g. HTTP method, service op name).
    pub kind: String,
    /// Out-of-band attributes attached to the message.
    pub meta: Vec<MetaEntry>,
}

/// gRPC-style error codes for WAFER.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub enum ErrorCode {
    /// Operation completed successfully (rarely used in errors).
    Ok,
    /// Operation was cancelled by the caller.
    Cancelled,
    /// Unknown error; the source did not classify it.
    Unknown,
    /// Caller supplied an invalid argument.
    InvalidArgument,
    /// Deadline expired before the operation could complete.
    DeadlineExceeded,
    /// Requested resource does not exist.
    NotFound,
    /// Resource being created already exists.
    AlreadyExists,
    /// Caller lacks permission for the operation.
    PermissionDenied,
    /// A quota or rate limit was exhausted.
    ResourceExhausted,
    /// Operation rejected because the system is not in the required state.
    FailedPrecondition,
    /// Operation was aborted (often due to a concurrency conflict).
    Aborted,
    /// Operation attempted past the valid range.
    OutOfRange,
    /// Operation is not implemented or not supported.
    Unimplemented,
    /// Internal invariant violated.
    Internal,
    /// Service is temporarily unavailable.
    Unavailable,
    /// Unrecoverable data loss or corruption.
    DataLoss,
    /// Caller did not provide valid authentication credentials.
    Unauthenticated,
}

impl fmt::Display for ErrorCode {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        fmt::Debug::fmt(self, f)
    }
}

impl ErrorCode {
    /// Stable numeric tag for the streaming-ABI error sentinel wire format.
    ///
    /// This is the **single source of truth** for the `ErrorCode` ↔ ordinal
    /// mapping used by the negative-sentinel encoding on the streaming ABI:
    /// the host encodes a failure as `-(code.to_ordinal())` (see
    /// `wafer-run`'s `error_code_to_neg_i32`/`_i64`), and guests decode it via
    /// [`ErrorCode::from_ordinal`] (see `wafer-sdk`'s stream driver and
    /// `wafer-core`'s wasm-component `call_service`). It is hand-rolled rather
    /// than derived from `as u8` so the wire mapping is independent of source
    /// ordering. `0` means "ok / no error"; values run `1..=16`.
    pub fn to_ordinal(self) -> u8 {
        match self {
            ErrorCode::Ok => 0,
            ErrorCode::Cancelled => 1,
            ErrorCode::Unknown => 2,
            ErrorCode::InvalidArgument => 3,
            ErrorCode::DeadlineExceeded => 4,
            ErrorCode::NotFound => 5,
            ErrorCode::AlreadyExists => 6,
            ErrorCode::PermissionDenied => 7,
            ErrorCode::ResourceExhausted => 8,
            ErrorCode::FailedPrecondition => 9,
            ErrorCode::Aborted => 10,
            ErrorCode::OutOfRange => 11,
            ErrorCode::Unimplemented => 12,
            ErrorCode::Internal => 13,
            ErrorCode::Unavailable => 14,
            ErrorCode::DataLoss => 15,
            ErrorCode::Unauthenticated => 16,
        }
    }

    /// Parse a snake_case (or hyphenated) wire string into an `ErrorCode`.
    ///
    /// For wire-decode boundaries that receive string-encoded codes from
    /// external sources (HTTP query forms, hand-written config). Returns
    /// `None` for unrecognized strings — callers decide how to handle the
    /// miss instead of silently degrading to [`ErrorCode::Unknown`] (the
    /// lossy behavior the removed `From<&str>` impl had).
    ///
    /// Rust code constructing errors should name the enum variant directly.
    pub fn parse(s: &str) -> Option<ErrorCode> {
        match s {
            "ok" => Some(Self::Ok),
            "cancelled" => Some(Self::Cancelled),
            "unknown" => Some(Self::Unknown),
            "invalid_argument" | "invalid-argument" | "bad_request" => Some(Self::InvalidArgument),
            "deadline_exceeded" | "deadline-exceeded" => Some(Self::DeadlineExceeded),
            "not_found" | "not-found" => Some(Self::NotFound),
            "already_exists" | "already-exists" => Some(Self::AlreadyExists),
            "permission_denied" | "permission-denied" => Some(Self::PermissionDenied),
            "resource_exhausted" | "resource-exhausted" => Some(Self::ResourceExhausted),
            "failed_precondition" | "failed-precondition" => Some(Self::FailedPrecondition),
            "aborted" => Some(Self::Aborted),
            "out_of_range" | "out-of-range" => Some(Self::OutOfRange),
            "unimplemented" | "not_implemented" => Some(Self::Unimplemented),
            "internal" => Some(Self::Internal),
            "unavailable" => Some(Self::Unavailable),
            "data_loss" | "data-loss" => Some(Self::DataLoss),
            "unauthenticated" => Some(Self::Unauthenticated),
            _ => None,
        }
    }

    /// Inverse of [`ErrorCode::to_ordinal`]. Unknown ordinals fall back to
    /// [`ErrorCode::Internal`] (the streaming ABI guarantees full structured
    /// detail is still retrievable via `take_error`, so an unrecognised tag
    /// degrades gracefully rather than panicking).
    pub fn from_ordinal(ordinal: u8) -> ErrorCode {
        match ordinal {
            0 => ErrorCode::Ok,
            1 => ErrorCode::Cancelled,
            2 => ErrorCode::Unknown,
            3 => ErrorCode::InvalidArgument,
            4 => ErrorCode::DeadlineExceeded,
            5 => ErrorCode::NotFound,
            6 => ErrorCode::AlreadyExists,
            7 => ErrorCode::PermissionDenied,
            8 => ErrorCode::ResourceExhausted,
            9 => ErrorCode::FailedPrecondition,
            10 => ErrorCode::Aborted,
            11 => ErrorCode::OutOfRange,
            12 => ErrorCode::Unimplemented,
            13 => ErrorCode::Internal,
            14 => ErrorCode::Unavailable,
            15 => ErrorCode::DataLoss,
            16 => ErrorCode::Unauthenticated,
            _ => ErrorCode::Internal,
        }
    }
}

/// A structured error returned by a block.
#[derive(Debug, Clone, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub struct WaferError {
    /// Coarse error classification, modeled on gRPC status codes.
    pub code: ErrorCode,
    /// Human-readable error message.
    pub message: String,
    /// Structured key/value attributes (e.g. resource name, retry hint).
    pub meta: Vec<MetaEntry>,
}

impl fmt::Display for WaferError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{:?}: {}", self.code, self.message)
    }
}

/// Declared block instance lifecycle — **advisory, not enforced**.
///
/// No runtime consumer reads this today. Actual instantiation behavior
/// is fixed by runtime type, regardless of the declared mode:
///
/// - **Native** blocks: one shared `Arc<dyn Block>` per registration —
///   effectively a per-runtime-process singleton serving concurrent
///   calls (blocks are `Send + Sync` and must be thread-safe).
/// - **WASM** blocks: a fresh store + instance for every call —
///   effectively `PerExecution`; no guest state survives between calls.
///
/// A WASM block that declares one of the state-retaining modes
/// (`Singleton`, `PerFlow`) draws a warning at `seal()`, since per-call
/// instantiation cannot honor it. Enforcement (a real instance manager
/// keyed on this declaration) is future work tied to instance pooling;
/// until then the declaration only documents intent.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub enum InstanceMode {
    /// One instance per node (the runtime process).
    PerNode,
    /// One instance shared across the entire deployment.
    Singleton,
    /// One instance per flow definition.
    PerFlow,
    /// A fresh instance for every execution.
    PerExecution,
}

/// The kind of lifecycle event.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub enum LifecycleType {
    /// First-time initialization (run migrations, seed defaults).
    Init,
    /// Block is being brought online and may begin serving requests.
    Start,
    /// Block is being shut down; release resources.
    Stop,
}

/// A lifecycle event sent to blocks during transitions.
#[derive(Debug, Clone, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub struct LifecycleEvent {
    /// Which lifecycle transition triggered this event.
    pub event_type: LifecycleType,
    /// Opaque event payload (codec-encoded by the sender).
    pub data: Vec<u8>,
}

/// A named binary blob carried alongside a `call_block` invocation.
///
/// Attached by the caller via `Context::call_block_with_attachments` (or, on
/// wasmi guests, the SDK's `RequestStream::attach`); read by the callee via
/// `Context::lookup_attachment`. Lifetime is per-`call_block` invocation —
/// attachments do not propagate beyond the immediate callee.
///
/// Encoded via `wafer_block::codec` (rmp-serde), so multi-MiB byte payloads
/// cross the host↔guest boundary without JSON-array inflation.
#[derive(Debug, Clone, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub struct Attachment {
    /// MIME type of the payload (e.g. `image/png`, `application/pdf`).
    pub mime: String,
    /// Raw payload bytes (not base64 — encoded directly by MessagePack).
    pub bytes: Vec<u8>,
    /// Optional client-supplied filename.
    pub filename: Option<String>,
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_error_code_serialization() {
        let json = serde_json::to_string(&ErrorCode::Internal).unwrap();
        assert_eq!(json, "\"Internal\"");

        let code: ErrorCode = serde_json::from_str("\"InvalidArgument\"").unwrap();
        assert_eq!(code, ErrorCode::InvalidArgument);
    }

    #[test]
    fn error_code_ordinal_round_trips_every_variant() {
        // Every variant must survive to_ordinal → from_ordinal unchanged.
        // This is the contract the host (encode) and guests (decode) rely on.
        for code in [
            ErrorCode::Ok,
            ErrorCode::Cancelled,
            ErrorCode::Unknown,
            ErrorCode::InvalidArgument,
            ErrorCode::DeadlineExceeded,
            ErrorCode::NotFound,
            ErrorCode::AlreadyExists,
            ErrorCode::PermissionDenied,
            ErrorCode::ResourceExhausted,
            ErrorCode::FailedPrecondition,
            ErrorCode::Aborted,
            ErrorCode::OutOfRange,
            ErrorCode::Unimplemented,
            ErrorCode::Internal,
            ErrorCode::Unauthenticated,
            ErrorCode::Unavailable,
            ErrorCode::DataLoss,
        ] {
            assert_eq!(ErrorCode::from_ordinal(code.to_ordinal()), code);
        }
    }

    #[test]
    fn error_code_from_ordinal_pins_wire_values() {
        // Pin the exact wire numbers — changing any of these is a breaking
        // ABI change for already-compiled guests.
        assert_eq!(ErrorCode::Ok.to_ordinal(), 0);
        assert_eq!(ErrorCode::NotFound.to_ordinal(), 5);
        assert_eq!(ErrorCode::Unimplemented.to_ordinal(), 12);
        assert_eq!(ErrorCode::Internal.to_ordinal(), 13);
        assert_eq!(ErrorCode::Unauthenticated.to_ordinal(), 16);
    }

    #[test]
    fn error_code_parse_accepts_wire_vocabulary() {
        assert_eq!(ErrorCode::parse("not_found"), Some(ErrorCode::NotFound));
        assert_eq!(ErrorCode::parse("not-found"), Some(ErrorCode::NotFound));
        assert_eq!(
            ErrorCode::parse("bad_request"),
            Some(ErrorCode::InvalidArgument)
        );
        assert_eq!(
            ErrorCode::parse("unauthenticated"),
            Some(ErrorCode::Unauthenticated)
        );
    }

    #[test]
    fn error_code_parse_rejects_unknown_strings() {
        // Explicitly NOT the lossy `From<&str>` behavior — unknown strings
        // surface as None, not ErrorCode::Unknown.
        assert_eq!(ErrorCode::parse("definitely_not_a_code"), None);
        assert_eq!(ErrorCode::parse(""), None);
        // Variant (CamelCase) names are the serde wire format, not this one.
        assert_eq!(ErrorCode::parse("NotFound"), None);
    }

    #[test]
    fn error_code_from_ordinal_unknown_falls_back_to_internal() {
        assert_eq!(ErrorCode::from_ordinal(17), ErrorCode::Internal);
        assert_eq!(ErrorCode::from_ordinal(99), ErrorCode::Internal);
        assert_eq!(ErrorCode::from_ordinal(255), ErrorCode::Internal);
    }

    #[test]
    fn test_instance_mode_serialization() {
        let json = serde_json::to_string(&InstanceMode::PerNode).unwrap();
        assert_eq!(json, "\"PerNode\"");

        let mode: InstanceMode = serde_json::from_str("\"Singleton\"").unwrap();
        assert_eq!(mode, InstanceMode::Singleton);
    }

    #[test]
    fn message_has_no_data_field() {
        let m = Message {
            kind: "POST".to_string(),
            meta: vec![MetaEntry {
                key: "k".into(),
                value: "v".into(),
            }],
        };
        assert_eq!(m.kind, "POST");
        assert_eq!(m.meta.len(), 1);
    }

    #[test]
    fn attachment_codec_roundtrip_no_inflation() {
        use crate::codec;
        let original = Attachment {
            mime: "image/png".into(),
            bytes: vec![0u8; 1024 * 1024],
            filename: Some("cat.png".into()),
        };
        let encoded = codec::encode(&original).expect("encode");
        // 1 MiB body + small framing for {mime, filename}. Allow 5% headroom —
        // the load-bearing invariant: rmp does not array-encode Vec<u8>.
        assert!(
            encoded.len() < 1024 * 1024 + (1024 * 1024 / 20),
            "encoded size {} exceeds 1.05 MiB — Attachment::bytes inflation regressed",
            encoded.len()
        );
        let decoded: Attachment = codec::decode(&encoded).expect("decode");
        assert_eq!(decoded.mime, "image/png");
        assert_eq!(decoded.bytes.len(), 1024 * 1024);
        assert_eq!(decoded.filename.as_deref(), Some("cat.png"));
    }
}
